def fit_weighted(self, grid, backend_func):
    """Regression using weighted least squares for heteroscedastic data."""
    X, y = np.c_[np.ones(len(self.x)), self.x], self.y
    grid_X = np.c_[np.ones(len(grid)), grid]

    yhat = backend_func(X, y, grid_X)
    if self.ci is None:
        return yhat, None

    def reg_func(_x, _y):
        return backend_func(_x, _y, grid_X)

    yhat_boots = algo.bootstrap(X, y,
                                func=reg_func,
                                n_boot=self.n_boot,
                                units=self.units,
                                seed=self.seed)
    return yhat, yhat_boots
